/**
 * FolderItem Component
 *
 * Renders a folder in the node pool with drag-and-drop support.
 * Supports nested folders and sorting.
 */

import { memo } from 'react'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import {
  Folder,
  FolderOpen,
  ChevronRight,
  ChevronDown,
  GripVertical,
} from 'lucide-react'
import { clsx } from 'clsx'
import type { NodePoolFolder, NodeCard } from '@/types'
import { createDraggableId } from '../types/node-pool'
import type { FolderItemProps } from '../types/node-pool'
import { NodeCardItem } from './NodeCardItem'

/**
 * Folder item component with drag and drop support
 */
export const FolderItem = memo(function FolderItem({
  folder,
  level = 0,
  cards,
  children,
  isDragOver,
  dragOverPosition,
  onToggle,
}: FolderItemProps) {
  const isCollapsed = folder.collapsed
  const dragId = createDraggableId('folder', folder.id)

  // Set up sortable for this folder
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: dragId,
    disabled: false,
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  // Calculate indentation based on nesting level
  const indentStyle = {
    paddingLeft: `${level * 16 + 8}px`,
  }

  const handleToggle = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    onToggle?.(folder.id)
  }

  return (
    <>
      {/* Drop indicator - before */}
      {isDragOver && dragOverPosition === 'before' && (
        <div className="h-0.5 bg-blue-500 rounded -mt-1 mb-1" style={{ marginLeft: `${level * 16 + 8}px` }} />
      )}

      {/* Folder header */}
      <div
        ref={setNodeRef}
        style={{ ...style, ...indentStyle }}
        data-dnd-id={dragId}
        className={clsx(
          'flex items-center gap-1 px-2 py-1.5 rounded-lg cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors',
          isDragging && 'opacity-50',
          isDragOver && dragOverPosition === 'inside' && 'bg-blue-100 dark:bg-blue-900/40 ring-2 ring-blue-400'
        )}
        {...attributes}
      >
        {/* Drag handle */}
        <div
          className="cursor-grab active:cursor-grabbing text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
          onClick={(e) => e.stopPropagation()}
          {...listeners}
        >
          <GripVertical className="w-3.5 h-3.5" />
        </div>

        {/* Expand/collapse indicator */}
        <button
          onClick={handleToggle}
          className="hover:bg-gray-200 dark:hover:bg-gray-600 rounded p-0.5"
        >
          {children.length > 0 || cards.length > 0 ? (
            isCollapsed ? (
              <ChevronRight className="w-3.5 h-3.5 text-gray-500" />
            ) : (
              <ChevronDown className="w-3.5 h-3.5 text-gray-500" />
            )
          ) : (
            <div className="w-3.5 h-3.5" />
          )}
        </button>

        {/* Folder icon */}
        {isCollapsed ? (
          <Folder className="w-4 h-4 text-gray-400 dark:text-gray-500" />
        ) : (
          <FolderOpen className="w-4 h-4 text-blue-500" />
        )}

        {/* Folder name */}
        <span className="text-sm font-medium text-gray-700 dark:text-gray-300 flex-1 truncate">
          {folder.name}
        </span>

        {/* Card count */}
        <span className="text-xs text-gray-500 dark:text-gray-400">
          {cards.length}
        </span>
      </div>

      {/* Folder contents (when expanded) */}
      {!isCollapsed && (
        <div className="ml-4 pl-2 border-l border-gray-200 dark:border-gray-700 my-1 space-y-1">
          {/* Cards in this folder */}
          {cards.map((card) => (
            <div key={card.id} className="py-0.5">
              <NodeCardItem
                card={card}
                isDragging={false}
                isDragOver={false}
                dragOverPosition={null}
                onUse={(c) => {
                  // TODO: Implement use card
                }}
                onRemove={(id) => {
                  // TODO: Implement remove
                }}
                onSaveName={(id, name) => {
                  // TODO: Implement save name
                }}
                onContextMenu={(e, c) => {
                  e.preventDefault()
                  // TODO: Context menu
                }}
              />
            </div>
          ))}

          {/* Nested folders */}
          {children.map((child) => (
            <FolderItem
              key={child.id}
              folder={child}
              level={level + 1}
              cards={[]} // Cards will be passed from parent
              children={child.children || []}
              isDragOver={false}
              dragOverPosition={null}
              onToggle={onToggle}
            />
          ))}
        </div>
      )}

      {/* Drop indicator - after */}
      {isDragOver && dragOverPosition === 'after' && (
        <div className="h-0.5 bg-blue-500 rounded -mb-1 mt-1" style={{ marginLeft: `${level * 16 + 8}px` }} />
      )}
    </>
  )
})

export type { FolderItemProps }
