/**
 * NodeCardItem Component
 *
 * Renders a node card in the node pool with drag-and-drop support.
 * Can be dragged within the pool (to reorder) or to the canvas (to use).
 */

import { useState, useCallback, memo } from 'react'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { Trash2 } from 'lucide-react'
import { clsx } from 'clsx'
import type { NodeCard } from '@/types'
import { createDraggableId } from '../types/node-pool'
import type { NodeCardItemProps } from '../types/node-pool'

/**
 * Node card item component with drag and drop support
 */
export const NodeCardItem = memo(function NodeCardItem({
  card,
  isDragging: isDraggingProp,
  isDragOver,
  dragOverPosition,
  onUse,
  onRemove,
  onSaveName,
  onContextMenu,
}: NodeCardItemProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(card.name)
  const [showPreview, setShowPreview] = useState(false)

  const dragId = createDraggableId('card', card.id)

  // Set up sortable for this card
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging: isDraggingLocal,
  } = useSortable({
    id: dragId,
    disabled: false,
  })

  const isDragging = isDraggingProp || isDraggingLocal

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    backgroundColor: card.color || '#ffffff',
  }

  const handleSave = useCallback(async () => {
    if (editName.trim() && editName.trim() !== card.name) {
      await onSaveName(card.id, editName.trim())
    }
    setIsEditing(false)
    setEditName(card.name)
  }, [card.id, card.name, editName, onSaveName])

  const handleCancel = useCallback(() => {
    setIsEditing(false)
    setEditName(card.name)
  }, [card.name])

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      handleSave()
    } else if (e.key === 'Escape') {
      e.preventDefault()
      handleCancel()
    }
  }, [handleSave, handleCancel])

  const handleCardClick = useCallback((e: React.MouseEvent) => {
    // Don't toggle preview if editing or interacting with controls
    if (isEditing || e.target !== e.currentTarget) {
      return
    }
    setShowPreview(!showPreview)
  }, [isEditing, showPreview])

  // Parse card content for display
  const parseCardContent = useCallback(() => {
    try {
      const nodeData = JSON.parse(card.content)
      return {
        type: nodeData.type || 'text',
        title: nodeData.title || card.name,
        content: nodeData.content || '',
        imageUrl: nodeData.imageUrl || null,
        color: nodeData.color || card.color,
      }
    } catch {
      return {
        type: 'text',
        title: card.name,
        content: card.content,
        imageUrl: null,
        color: card.color,
      }
    }
  }, [card])

  const contentData = parseCardContent()

  return (
    <>
      {/* Drop indicator - above */}
      {isDragOver && dragOverPosition === 'before' && (
        <div className="h-0.5 bg-blue-500 rounded -mt-1 mb-1" />
      )}

      {/* Card */}
      <div
        ref={setNodeRef}
        style={style}
        data-dnd-id={dragId}
        className={clsx(
          'p-3 rounded-lg border hover:border-blue-400 dark:hover:border-blue-500 cursor-pointer group relative transition-all duration-200 hover:shadow-md',
          isDragging && 'opacity-50 rotate-2 scale-105',
          isDragOver && dragOverPosition === 'inside' && 'ring-2 ring-blue-500'
        )}
        onClick={handleCardClick}
        onContextMenu={(e) => onContextMenu(e, card)}
        {...attributes}
      >
        <div className="flex items-start justify-between">
          <div className="flex-1 min-w-0">
            {isEditing ? (
              <input
                type="text"
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                onBlur={handleSave}
                onKeyDown={handleKeyDown}
                className="w-full px-1 py-0.5 text-sm bg-white dark:bg-gray-800 border border-blue-500 rounded outline-none"
                autoFocus
                onClick={(e) => e.stopPropagation()}
              />
            ) : (
              <h4 className="text-sm font-medium text-gray-800 dark:text-white truncate">
                {card.name}
              </h4>
            )}
            {card.description && !isEditing && (
              <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                {card.description}
              </p>
            )}
          </div>

          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button
              onClick={(e) => {
                e.stopPropagation()
                onRemove(card.id)
              }}
              className="p-1.5 rounded-lg hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400 bg-white/50 dark:bg-gray-800/50 backdrop-blur-sm shadow-sm border border-red-200 dark:border-red-900/50"
              title="删除"
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

        <div className="mt-2 text-xs text-gray-400 dark:text-gray-500">
          添加于 {new Date(card.createdAt).toLocaleDateString()}
        </div>

        {/* Preview tooltip (simplified for now) */}
        {showPreview && (
          <div className="fixed z-[9999] bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-gray-300 dark:border-gray-600 p-4 max-w-xs">
            <h5 className="text-sm font-semibold mb-2">{contentData.title}</h5>
            {contentData.type === 'image' && contentData.imageUrl ? (
              <img src={contentData.imageUrl} alt={contentData.title} className="w-full h-auto rounded" />
            ) : (
              <p className="text-xs text-gray-600 dark:text-gray-400 line-clamp-3">
                {contentData.content || '暂无内容'}
              </p>
            )}
          </div>
        )}
      </div>

      {/* Drop indicator - below */}
      {isDragOver && dragOverPosition === 'after' && (
        <div className="h-0.5 bg-blue-500 rounded -mb-1 mt-1" />
      )}
    </>
  )
})

export type { NodeCardItemProps }
