/**
 * Node Pool Feature - Type Definitions
 *
 * This file contains all type definitions for the node pool feature.
 * It provides complete type safety and eliminates the need for 'any' types.
 */

import type { NodeCard, NodePoolFolder } from '@/types'

// Re-export base types from the main types file
export type { NodeCard, NodePoolFolder }

/**
 * Unique identifier for each draggable item in the @dnd-kit system
 * Format: 'folder:{id}' or 'card:{id}'
 */
export type DraggableId = `folder:${number}` | `card:${number}`

/**
 * The type of draggable item
 */
export type DraggableType = 'folder' | 'card'

/**
 * Parse a draggable ID to extract its type and numeric ID
 */
export function parseDraggableId(id: DraggableId): { type: DraggableType; numericId: number } {
  const [type, numericId] = id.split(':') as [DraggableType, string]
  return { type, numericId: Number.parseInt(numericId, 10) }
}

/**
 * Create a draggable ID from type and numeric ID
 */
export function createDraggableId(type: DraggableType, numericId: number): DraggableId {
  return `${type}:${numericId}` as DraggableId
}

/**
 * Data carried during drag operations
 */
export interface DragData {
  /** Unique draggable identifier */
  id: DraggableId
  /** Type of the draggable item */
  type: DraggableType
  /** Numeric ID from the database */
  numericId: number
  /** For cards: the folder ID they belong to (null if at root) */
  folderId: number | null
  /** For folders: the parent folder ID (null if at root level) */
  parentId: number | null
}

/**
 * The drop position relative to the target item
 */
export type DropPosition = 'before' | 'after' | 'inside'

/**
 * Information about the item being dragged over
 */
export interface DragOverData {
  /** ID of the item being hovered over */
  id: DraggableId
  /** Type of the item being hovered over */
  type: DraggableType
  /** Numeric ID from the database */
  numericId: number
  /** Position relative to the hovered item */
  position: DropPosition
}

/**
 * Complete drag state
 */
export interface DragState {
  /** The item currently being dragged (if any) */
  active: DragData | null
  /** The item currently being dragged over (if any) */
  over: DragOverData | null
}

/**
 * A reordering operation to be executed
 */
export interface ReorderOperation {
  /** Type of reorder operation */
  type: 'reorder-folder' | 'reorder-card'
  /** ID of the item being reordered */
  itemId: number
  /** ID of the target item (to reorder before/after) */
  targetId: number
  /** Where to place the item relative to the target */
  position: 'before' | 'after'
  /** For cards: the folder containing both items */
  folderId: number | null
  /** For folders: the parent containing both folders */
  parentId: number | null
}

/**
 * Result of a reorder calculation
 */
export interface ReorderResult {
  /** Items with updated sort orders */
  updates: Array<{ id: number; sortOrder: number }>
  /** New index of the dragged item */
  newIndex: number
  /** Old index of the dragged item */
  oldIndex: number
}

/**
 * Node pool store state
 */
export interface NodePoolStoreState {
  /** Map of all cards for O(1) lookup */
  cardsMap: Map<number, NodeCard>
  /** Map of all folders for O(1) lookup */
  foldersMap: Map<number, NodePoolFolder>
  /** Current drag state */
  dragState: DragState
  /** Loading state */
  isLoading: boolean
  /** Error message (if any) */
  error: string | null
}

/**
 * Node pool store actions
 */
export interface NodePoolStoreActions {
  // Card actions
  getCard: (id: number) => NodeCard | undefined
  setCards: (cards: NodeCard[]) => void
  updateCard: (id: number, data: Partial<NodeCard>) => Promise<void>
  removeCard: (id: number) => Promise<void>
  reorderCards: (updates: Array<{ id: number; sortOrder: number }>) => Promise<void>

  // Folder actions
  getFolder: (id: number) => NodePoolFolder | undefined
  setFolders: (folders: NodePoolFolder[]) => void
  createFolder: (data: Omit<NodePoolFolder, 'id' | 'createdAt' | 'children'>) => Promise<NodePoolFolder>
  updateFolder: (id: number, data: Partial<NodePoolFolder>) => Promise<void>
  removeFolder: (id: number) => Promise<void>
  reorderFolders: (updates: Array<{ id: number; sortOrder: number }>) => Promise<void>
  toggleFolderCollapsed: (id: number) => void

  // Drag state actions
  setDragState: (state: DragState) => void
  clearDragState: () => void

  // Utility actions
  clearError: () => void
  reset: () => void
}

/**
 * Complete node pool store interface
 */
export interface NodePoolStore extends NodePoolStoreState, NodePoolStoreActions {}

/**
 * Options for useNodePoolDrag hook
 */
export interface UseNodePoolDragOptions {
  /** Callback when drag starts */
  onDragStart?: (data: DragData) => void
  /** Callback when drag ends */
  onDragEnd?: (data: DragData | null) => void
  /** Callback to execute reorder operation */
  onReorder: (operation: ReorderOperation) => Promise<void>
  /** Callback when item is dropped on canvas (outside node pool) */
  onDropOnCanvas?: (data: DragData, position: { x: number; y: number }) => Promise<void>
}

/**
 * Return value for useNodePoolDrag hook
 */
export interface UseNodePoolDragReturn {
  /** @dnd-kit sensors for drag detection */
  sensors: any[]
  /** Current drag data */
  activeDragData: DragData | null
  /** Function to set drag over state */
  setDragOver: (over: DragOverData | null) => void
}

/**
 * Options for useNodePoolSort hook
 */
export interface UseNodePoolSortOptions {
  /** Whether to enable sorting */
  enabled?: boolean
}

/**
 * Return value for useNodePoolSort hook
 */
export interface UseNodePoolSortReturn {
  /** Sorted folders at root level */
  sortedRootFolders: NodePoolFolder[]
  /** Sorted cards grouped by folder ID (null = root level) */
  sortedCardsByFolder: Map<number | null, NodeCard[]>
  /** Function to get the position of an item */
  getItemPosition: (id: number, type: DraggableType) => { index: number; folderId: number | null } | null
  /** Function to handle reordering */
  handleReorder: (operation: ReorderOperation) => Promise<void>
}

/**
 * Tree node for folder hierarchy
 */
export interface FolderTreeNode extends NodePoolFolder {
  /** Child folders */
  children: FolderTreeNode[]
}

/**
 * Props for FolderItem component
 */
export interface FolderItemProps {
  /** Folder data */
  folder: NodePoolFolder
  /** Nesting depth level */
  level?: number
  /** Cards in this folder */
  cards: NodeCard[]
  /** Child folders */
  children: NodePoolFolder[]
  /** Whether folder is being dragged over */
  isDragOver: boolean
  /** Drag over position */
  dragOverPosition: DropPosition | null
  /** Callback when folder is toggled */
  onToggle?: (id: number) => void
}

/**
 * Props for NodeCardItem component
 */
export interface NodeCardItemProps {
  /** Card data */
  card: NodeCard
  /** Whether card is being dragged */
  isDragging: boolean
  /** Whether card is being dragged over */
  isDragOver: boolean
  /** Drag over position */
  dragOverPosition: DropPosition | null
  /** Callback to use the card */
  onUse: (card: NodeCard) => void
  /** Callback to remove the card */
  onRemove: (id: number) => void
  /** Callback to save card name */
  onSaveName: (id: number, name: string) => void
  /** Callback to show context menu */
  onContextMenu: (event: React.MouseEvent, card: NodeCard) => void
}

/**
 * Props for DragOverlay component
 */
export interface DragOverlayProps {
  /** Current drag data */
  activeDragData: DragData | null
}

/**
 * Sort calculation options
 */
export interface SortCalculateOptions {
  /** Current sort order step (default: 10) */
  step?: number
  /** Minimum sort order (default: 0) */
  minSortOrder?: number
}

/**
 * Batch update result
 */
export interface BatchUpdateResult {
  /** Number of successful updates */
  successCount: number
  /** Number of failed updates */
  failureCount: number
  /** Errors from failed updates */
  errors: Array<{ id: number; error: string }>
}
