import { useState, useRef, useEffect } from 'react'
import { Plus, Folder, FolderOpen, FileText, Trash2, MoreVertical, Edit2, Check, X, FolderKanban, Calendar, GripVertical } from 'lucide-react'
import { useNavigate, useLocation } from 'react-router-dom'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useUIStore } from '@/store/useUIStore'
import clsx from 'clsx'

interface SidebarProps {
  open: boolean
}

export function Sidebar({ open }: SidebarProps) {
  const navigate = useNavigate()
  const location = useLocation()
  const canvasIdMatch = location.pathname.match(/\/canvas\/(\d+)/)
  const activeCanvasId = canvasIdMatch ? parseInt(canvasIdMatch[1]) : null
  const { projects, canvases, folders, currentProject, createCanvas, createFolder, updateCanvas, updateProject, deleteProject, setCurrentProject, loadProjects, reorderFolders, reorderCanvases } = useProjectsStore()
  const { addToast } = useUIStore()

  // 判断当前是否在项目页面
  const isProjectsPage = location.pathname === '/projects'

  // 管理文件夹展开状态
  const [expandedFolderIds, setExpandedFolderIds] = useState<Set<number>>(new Set())

  // 拖拽状态
  const [draggedItem, setDraggedItem] = useState<{
    type: 'folder' | 'canvas'
    id: number
    parentId: number | null
  } | null>(null)

  const [dragOverItem, setDragOverItem] = useState<{
    type: 'folder' | 'canvas'
    id: number
    parentId: number | null
    position: 'before' | 'after' | null
  } | null>(null)

  // 其他状态
  const [editingProjectId, setEditingProjectId] = useState<number | null>(null)
  const [editProjectName, setEditProjectName] = useState('')
  const [editProjectDesc, setEditProjectDesc] = useState('')
  const [showProjectMenu, setShowProjectMenu] = useState<number | null>(null)
  const projectMenuRef = useRef<HTMLDivElement>(null)

  const rootCanvases = canvases.filter((c) => !c.folderId)

  const handleCreateCanvas = async () => {
    if (!currentProject) {
      addToast({ type: 'warning', title: '未选择项目', message: '请先选择一个项目' })
      return
    }

    try {
      await createCanvas(currentProject.id, {
        name: `未命名画布 ${canvases.length + 1}`,
        projectId: currentProject.id,
      })
    } catch (error) {
      addToast({ type: 'error', title: '创建画布失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleCreateFolder = async () => {
    if (!currentProject) {
      addToast({ type: 'warning', title: '未选择项目', message: '请先选择一个项目' })
      return
    }

    try {
      await createFolder(currentProject.id, {
        name: '新建文件夹',
        projectId: currentProject.id,
        parentId: null,
        sortOrder: folders.length,
      })
    } catch (error) {
      addToast({ type: 'error', title: '创建文件夹失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  // 切换文件夹展开状态
  const handleToggleFolder = (folderId: number) => {
    setExpandedFolderIds(prev => {
      const newSet = new Set(prev)
      if (newSet.has(folderId)) {
        newSet.delete(folderId)
      } else {
        newSet.add(folderId)
      }
      return newSet
    })
  }

  // 加载项目列表
  useEffect(() => {
    loadProjects()
  }, [loadProjects])

  // 点击外部关闭项目菜单
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (projectMenuRef.current && !projectMenuRef.current.contains(event.target as Node)) {
        setShowProjectMenu(null)
      }
    }

    if (showProjectMenu !== null) {
      document.addEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [showProjectMenu])

  const handleSelectProject = async (project: any) => {
    await setCurrentProject(project)
    navigate(`/canvas/new`)
  }

  const handleBackToProjects = () => {
    setCurrentProject(null)
    navigate('/projects')
  }

  const handleStartEditProject = (project: any) => {
    setEditProjectName(project.name)
    setEditProjectDesc(project.description || '')
    setEditingProjectId(project.id)
    setShowProjectMenu(null)
  }

  const handleSaveProject = async () => {
    if (!editProjectName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入项目名称' })
      return
    }

    if (!editingProjectId) return

    try {
      await updateProject(editingProjectId, {
        name: editProjectName.trim(),
        description: editProjectDesc.trim() || null,
      })
      addToast({ type: 'success', title: '已更新', message: '项目信息已更新' })
      setEditingProjectId(null)
    } catch (error) {
      addToast({ type: 'error', title: '更新失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleCancelEditProject = () => {
    setEditingProjectId(null)
    setEditProjectName('')
    setEditProjectDesc('')
  }

  const handleDeleteProject = async (project: any) => {
    if (!confirm(`确定要删除项目"${project.name}"吗？项目内的所有画布和文件夹也将被删除。此操作不可恢复。`)) {
      return
    }

    try {
      await deleteProject(project.id)
      addToast({ type: 'success', title: '已删除', message: '项目已被删除' })
      setShowProjectMenu(null)
    } catch (error) {
      addToast({ type: 'error', title: '删除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  // 拖拽事件处理函数
  const handleDragStart = (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => {
    e.dataTransfer.effectAllowed = 'move'
    const parentId = type === 'folder' ? item.parentId : item.folderId
    setDraggedItem({ type, id: item.id, parentId: parentId || null })
  }

  const handleDragOver = (e: React.DragEvent, targetItem: any, targetType: 'folder' | 'canvas') => {
    e.preventDefault()
    e.stopPropagation()

    if (!draggedItem || draggedItem.id === targetItem.id) {
      setDragOverItem(null)
      return
    }

    const targetParentId = targetType === 'folder' ? targetItem.parentId : targetItem.folderId

    // 约束：画布不能拖到同目录下文件夹的上方
    if (draggedItem.type === 'canvas' && targetType === 'folder' && draggedItem.parentId === targetParentId) {
      setDragOverItem(null)
      return
    }

    // 检测鼠标在目标元素中的位置（上半部分还是下半部分）
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect()
    const relativeY = e.clientY - rect.top
    const position = relativeY < rect.height / 2 ? 'before' : 'after'

    setDragOverItem({ type: targetType, id: targetItem.id, parentId: targetParentId || null, position })
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()

    // 检查是否真的离开了元素（而不是进入子元素）
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect()
    const x = e.clientX
    const y = e.clientY

    if (x < rect.left || x >= rect.right || y < rect.top || y >= rect.bottom) {
      setDragOverItem(null)
    }
  }

  const handleDrop = async (e: React.DragEvent, targetItem: any, targetType: 'folder' | 'canvas') => {
    e.preventDefault()
    e.stopPropagation()

    if (!draggedItem || !dragOverItem) return

    const targetParentId = targetType === 'folder' ? targetItem.parentId : targetItem.folderId
    const draggedParentId = draggedItem.parentId

    // 只允许同类型之间的拖拽排序
    if (draggedItem.type !== targetType) {
      setDragOverItem(null)
      setDraggedItem(null)
      return
    }

    // 执行排序逻辑，传递插入位置
    await reorderItems(draggedItem.type, draggedItem.id, targetItem.id, targetParentId || null, dragOverItem.position)

    setDragOverItem(null)
    setDraggedItem(null)
  }

  const reorderItems = async (
    type: 'folder' | 'canvas',
    draggedId: number,
    targetId: number,
    parentId: number | null,
    position: 'before' | 'after' | null
  ) => {
    const items = type === 'folder' ? folders : canvases
    const siblings = items.filter((item: any) => {
      const itemParentId = type === 'folder' ? item.parentId : item.folderId
      return itemParentId === parentId
    })

    const sortedSiblings = [...siblings].sort((a: any, b: any) => a.sortOrder - b.sortOrder)

    const draggedIndex = sortedSiblings.findIndex((item: any) => item.id === draggedId)
    const targetIndex = sortedSiblings.findIndex((item: any) => item.id === targetId)

    if (draggedIndex === -1 || targetIndex === -1) return

    const [draggedItem] = sortedSiblings.splice(draggedIndex, 1)

    // 根据插入位置决定插入索引
    // 如果是 'before'，插入到目标位置；如果是 'after'，插入到目标位置+1
    // 但因为已经移除了被拖拽的元素，需要调整索引
    let insertIndex = targetIndex
    if (position === 'after') {
      // 如果拖拽元素在目标元素上方，插入索引需要-1
      if (draggedIndex < targetIndex) {
        insertIndex = targetIndex - 1
      } else {
        insertIndex = targetIndex
      }
    } else {
      // before
      if (draggedIndex < targetIndex) {
        insertIndex = targetIndex - 1
      } else {
        insertIndex = targetIndex
      }
    }

    sortedSiblings.splice(insertIndex, 0, draggedItem)

    const sortOrderStep = 10
    const updates = sortedSiblings.map((item: any, index: number) => ({
      id: item.id,
      sortOrder: index * sortOrderStep,
    }))

    if (type === 'folder') {
      await reorderFolders(updates)
    } else {
      await reorderCanvases(updates)
    }
  }

  return (
    <aside
      className={clsx(
        'bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 flex flex-col transition-all duration-200',
        open ? 'w-64' : 'w-0'
      )}
    >
      {isProjectsPage || !currentProject ? (
        // 项目选择视图
        <>
          <div className="h-14 border-b border-gray-200 dark:border-gray-700 flex items-center px-4 flex-shrink-0">
            <h2 className="font-semibold text-gray-800 dark:text-white">项目</h2>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar p-3">
            {projects.length === 0 ? (
              <div className="text-center py-8">
                <FolderKanban className="w-12 h-12 text-gray-400 mx-auto mb-3" />
                <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">还没有项目</p>
                <button
                  onClick={() => navigate('/projects')}
                  className="text-sm text-blue-600 dark:text-blue-400 hover:underline"
                >
                  创建项目
                </button>
              </div>
            ) : (
              <div className="space-y-2">
                {projects.map((project) => (
                  <div
                    key={project.id}
                    className={clsx(
                      'p-3 rounded-lg transition-colors group',
                      editingProjectId === project.id
                        ? 'bg-blue-50 dark:bg-blue-900/30'
                        : 'bg-gray-50 dark:bg-gray-700 hover:bg-blue-50 dark:hover:bg-blue-900/20'
                    )}
                  >
                    {editingProjectId === project.id ? (
                      // 编辑模式
                      <div className="space-y-2">
                        <input
                          type="text"
                          value={editProjectName}
                          onChange={(e) => setEditProjectName(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && handleSaveProject()}
                          placeholder="项目名称"
                          className="w-full px-2 py-1 text-sm bg-white dark:bg-gray-800 border border-blue-500 rounded focus:outline-none text-gray-900 dark:text-white"
                          autoFocus
                        />
                        <textarea
                          value={editProjectDesc}
                          onChange={(e) => setEditProjectDesc(e.target.value)}
                          placeholder="描述（可选）"
                          rows={2}
                          className="w-full px-2 py-1 text-sm bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded focus:outline-none text-gray-900 dark:text-white resize-none"
                        />
                        <div className="flex items-center gap-2">
                          <button
                            onClick={handleSaveProject}
                            className="flex items-center gap-1 px-2 py-1 text-xs bg-green-600 hover:bg-green-700 text-white rounded transition-colors"
                          >
                            <Check className="w-3 h-3" />
                            保存
                          </button>
                          <button
                            onClick={handleCancelEditProject}
                            className="flex items-center gap-1 px-2 py-1 text-xs bg-gray-400 hover:bg-gray-500 text-white rounded transition-colors"
                          >
                            <X className="w-3 h-3" />
                            取消
                          </button>
                        </div>
                      </div>
                    ) : (
                      // 查看模式
                      <div
                        onClick={() => handleSelectProject(project)}
                        className="cursor-pointer"
                      >
                        <div className="flex items-start justify-between">
                          <div className="flex-1 min-w-0 pr-2">
                            <h3 className="font-medium text-gray-900 dark:text-white text-sm truncate">
                              {project.name}
                            </h3>
                            {project.description && (
                              <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                                {project.description}
                              </p>
                            )}
                            <div className="flex items-center gap-2 mt-2 text-xs text-gray-500 dark:text-gray-400">
                              <Calendar className="w-3 h-3" />
                              <span>{new Date(project.updatedAt).toLocaleDateString()}</span>
                            </div>
                          </div>
                          <div className="relative" ref={projectMenuRef}>
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                setShowProjectMenu(showProjectMenu === project.id ? null : project.id)
                              }}
                              className="opacity-0 group-hover:opacity-100 p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-600"
                            >
                              <MoreVertical className="w-4 h-4 text-gray-600 dark:text-gray-400" />
                            </button>

                            {/* 下拉菜单 */}
                            {showProjectMenu === project.id && (
                              <div className="absolute right-0 top-full mt-1 w-32 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50">
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    handleStartEditProject(project)
                                  }}
                                  className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                                >
                                  <Edit2 className="w-3 h-3" />
                                  重命名
                                </button>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    handleDeleteProject(project)
                                  }}
                                  className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30"
                                >
                                  <Trash2 className="w-3 h-3" />
                                  删除
                                </button>
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      ) : (
        // 项目和画布管理视图
        <>
          {/* 项目信息区域 */}
          <div className="border-b border-gray-200 dark:border-gray-700">
            <div className="p-4">
              <div className="flex items-center justify-between mb-3">
                <button
                  onClick={handleBackToProjects}
                  className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
                >
                  <FolderKanban className="w-4 h-4" />
                  返回项目列表
                </button>
              </div>
              <div className="bg-gradient-to-br from-blue-600/10 to-indigo-600/10 dark:from-blue-600/20 dark:to-indigo-600/20 rounded-xl p-3 border border-blue-100 dark:border-blue-900/30">
                <div className="flex items-center gap-2 mb-1">
                  <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
                  <span className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider">当前项目</span>
                </div>
                <h3 className="font-bold text-gray-900 dark:text-gray-100 truncate text-sm">
                  {currentProject.name}
                </h3>
                {currentProject.description && (
                  <p className="text-[11px] text-gray-500 dark:text-gray-400 mt-1 line-clamp-2 leading-relaxed">
                    {currentProject.description}
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* 画布管理区域 */}
          <div className="flex-1 flex flex-col min-h-0">
            <div className="h-12 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between px-4 flex-shrink-0">
              <h2 className="font-semibold text-gray-800 dark:text-white">画布管理</h2>
              <div className="flex items-center gap-1">
                <button
                  onClick={handleCreateFolder}
                  className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                  title="新建文件夹"
                >
                  <Folder className="w-4 h-4" />
                </button>
                <button
                  onClick={handleCreateCanvas}
                  className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                  title="新建画布"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
              {/* 文件夹列表 */}
              {folders
                .filter(f => !f.parentId)
                .sort((a, b) => a.sortOrder - b.sortOrder)
                .map((folder) => (
                  <FolderItem
                    key={folder.id}
                    folder={folder}
                    canvases={canvases}
                    activeCanvasId={activeCanvasId}
                    isExpanded={expandedFolderIds.has(folder.id)}
                    onToggle={handleToggleFolder}
                    dragOverItem={dragOverItem}
                    onDragStart={handleDragStart}
                    onDragOver={handleDragOver}
                    onDragLeave={handleDragLeave}
                    onDrop={handleDrop}
                  />
                ))}

              {/* 根目录画布 */}
              <div className="rounded transition-colors">
                {rootCanvases
                  .sort((a, b) => a.sortOrder - b.sortOrder)
                  .map((canvas) => (
                    <CanvasItem
                      key={canvas.id}
                      canvas={canvas}
                      isActive={activeCanvasId === canvas.id}
                      dragOverItem={dragOverItem}
                      onDragStart={handleDragStart}
                      onDragOver={handleDragOver}
                      onDragLeave={handleDragLeave}
                      onDrop={handleDrop}
                    />
                  ))}
              </div>
            </div>
          </div>
        </>
      )}
    </aside>
  )
}

function FolderItem({
  folder,
  canvases,
  activeCanvasId,
  isExpanded,
  onToggle,
  dragOverItem,
  onDragStart,
  onDragOver,
  onDragLeave,
  onDrop,
}: {
  folder: any
  canvases: any[]
  activeCanvasId: number | null
  isExpanded: boolean
  onToggle: (folderId: number) => void
  dragOverItem: { type: string; id: number; position: 'before' | 'after' | null } | null
  onDragStart: (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => void
  onDragOver: (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => void
  onDragLeave: (e: React.DragEvent) => void
  onDrop: (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => void
}) {
  const { updateFolder, deleteFolder } = useProjectsStore()
  const { addToast } = useUIStore()
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(folder.name)
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number } | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const contextMenuRef = useRef<HTMLDivElement>(null)

  // 点击外部关闭右键菜单
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
        setContextMenu(null)
      }
    }

    if (contextMenu) {
      document.addEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [contextMenu])

  // 进入编辑模式时聚焦输入框
  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [isEditing])

  const handleToggle = () => {
    if (!isEditing) {
      onToggle(folder.id)
    }
  }

  const handleStartEdit = () => {
    setEditName(folder.name)
    setIsEditing(true)
    setContextMenu(null)
  }

  const handleSaveEdit = async () => {
    if (!editName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入文件夹名称' })
      return
    }

    if (editName === folder.name) {
      setIsEditing(false)
      return
    }

    try {
      await updateFolder(folder.id, { name: editName.trim() })
      addToast({ type: 'success', title: '已重命名', message: '文件夹名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '重命名失败', message: error instanceof Error ? error.message : '未知错误' })
    }
    setIsEditing(false)
  }

  const handleCancelEdit = () => {
    setEditName(folder.name)
    setIsEditing(false)
  }

  const handleDelete = async () => {
    const folderCanvases = canvases.filter((c) => c.folderId === folder.id)
    const confirmMessage = folderCanvases.length > 0
      ? `确定要删除文件夹"${folder.name}"吗？文件夹内的 ${folderCanvases.length} 个画布也将被删除。此操作不可恢复。`
      : `确定要删除文件夹"${folder.name}"吗？此操作不可恢复。`

    if (!confirm(confirmMessage)) {
      return
    }

    try {
      await deleteFolder(folder.id)
      addToast({ type: 'success', title: '已删除', message: '文件夹已被删除' })
    } catch (error) {
      addToast({ type: 'error', title: '删除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSaveEdit()
    } else if (e.key === 'Escape') {
      handleCancelEdit()
    }
  }

  const folderCanvases = canvases.filter((c) => c.folderId === folder.id)

  return (
    <div className="mb-2">
      {isEditing ? (
        // 编辑模式
        <div className="flex items-center gap-1 px-2 py-1.5 rounded bg-blue-50 dark:bg-blue-900/30">
          <Folder className="w-4 h-4 text-gray-400 flex-shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={editName}
            onChange={(e) => setEditName(e.target.value)}
            onKeyDown={handleKeyDown}
            className="flex-1 text-sm bg-transparent border-b border-blue-500 outline-none text-gray-700 dark:text-gray-300 px-1"
          />
          <button
            onClick={handleSaveEdit}
            className="p-1 rounded hover:bg-green-100 dark:hover:bg-green-900/30 text-green-600 dark:text-green-400"
            title="保存"
          >
            <Check className="w-3 h-3" />
          </button>
          <button
            onClick={handleCancelEdit}
            className="p-1 rounded hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400"
            title="取消"
          >
            <X className="w-3 h-3" />
          </button>
        </div>
      ) : (
        // 查看模式
        <div className="relative group">
          {/* 插入指示线 - 上方 */}
          {dragOverItem?.type === 'folder' && dragOverItem?.id === folder.id && dragOverItem?.position === 'before' && (
            <div className="absolute -top-1 left-0 right-0 h-0.5 bg-blue-500 rounded z-10" />
          )}
          {/* 插入指示线 - 下方 */}
          {dragOverItem?.type === 'folder' && dragOverItem?.id === folder.id && dragOverItem?.position === 'after' && (
            <div className="absolute -bottom-1 left-0 right-0 h-0.5 bg-blue-500 rounded z-10" />
          )}

          <div
            draggable
            onDragStart={(e) => onDragStart(e, folder, 'folder')}
            onDragOver={(e) => onDragOver(e, folder, 'folder')}
            onDragLeave={onDragLeave}
            onDrop={(e) => onDrop(e, folder, 'folder')}
            onClick={handleToggle}
            onContextMenu={(e) => {
              e.preventDefault()
              e.stopPropagation()
              setContextMenu({ x: e.clientX, y: e.clientY })
            }}
            className="w-full flex items-center gap-2 px-2 py-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 cursor-pointer"
          >
            <div onClick={(e) => e.stopPropagation()} className="cursor-grab active:cursor-grabbing">
              <GripVertical className="w-3 h-3 text-gray-400" />
            </div>
            <div onClick={(e) => e.stopPropagation()}>
              {isExpanded ? (
                <FolderOpen className="w-4 h-4" />
              ) : (
                <Folder className="w-4 h-4" />
              )}
            </div>
            <span className="text-sm flex-1 truncate font-medium">{folder.name}</span>
            <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 bg-gray-100 dark:bg-gray-700/50 px-1.5 py-0.5 rounded-full min-w-[20px] text-center">
              {folderCanvases.length}
            </span>
          </div>

          {isExpanded && (
            <div className="ml-4 pl-3 mt-1 border-l border-gray-100 dark:border-gray-700/50 space-y-0.5">
              {folderCanvases.map((canvas) => (
                <CanvasItem
                  key={canvas.id}
                  canvas={canvas}
                  isActive={activeCanvasId === canvas.id}
                  dragOverItem={dragOverItem}
                  onDragStart={onDragStart}
                  onDragOver={onDragOver}
                  onDragLeave={onDragLeave}
                  onDrop={onDrop}
                />
              ))}
              {folderCanvases.length === 0 && (
                <div className="text-center py-4 text-sm text-gray-400">
                  空文件夹
                </div>
              )}
            </div>
          )}

          {/* 右键菜单 */}
          {contextMenu && (
            <div
              ref={contextMenuRef}
              className="fixed bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50 min-w-[120px]"
              style={{
                left: contextMenu.x,
                top: contextMenu.y
              }}
            >
              <button
                onClick={() => {
                  handleStartEdit()
                  setContextMenu(null)
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                <Edit2 className="w-3 h-3" />
                重命名
              </button>
              <button
                onClick={() => {
                  handleDelete()
                  setContextMenu(null)
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30"
              >
                <Trash2 className="w-3 h-3" />
                删除
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function CanvasItem({
  canvas,
  isActive,
  dragOverItem,
  onDragStart,
  onDragOver,
  onDragLeave,
  onDrop,
}: {
  canvas: any
  isActive?: boolean
  dragOverItem: { type: string; id: number; position: 'before' | 'after' | null } | null
  onDragStart: (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => void
  onDragOver: (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => void
  onDragLeave: (e: React.DragEvent) => void
  onDrop: (e: React.DragEvent, item: any, type: 'folder' | 'canvas') => void
}) {
  const navigate = useNavigate()
  const { updateCanvas, deleteCanvas, folders } = useProjectsStore()
  const { addToast } = useUIStore()
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(canvas.name)
  const [showContextMenu, setShowContextMenu] = useState(false)
  const [showMoveMenu, setShowMoveMenu] = useState(false)
  const [contextMenuPosition, setContextMenuPosition] = useState({ x: 0, y: 0 })
  const inputRef = useRef<HTMLInputElement>(null)
  const contextMenuRef = useRef<HTMLDivElement>(null)

  // 点击外部关闭菜单
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
        setShowContextMenu(false)
        setShowMoveMenu(false)
      }
    }

    if (showContextMenu) {
      document.addEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [showContextMenu])

  // 进入编辑模式时聚焦输入框
  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [isEditing])

  const handleStartEdit = () => {
    setEditName(canvas.name)
    setIsEditing(true)
    setShowContextMenu(false)
  }

  const handleSaveEdit = async () => {
    if (!editName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入画布名称' })
      return
    }

    if (editName === canvas.name) {
      setIsEditing(false)
      return
    }

    try {
      await updateCanvas(canvas.id, { name: editName.trim() })
      addToast({ type: 'success', title: '已重命名', message: '画布名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '重命名失败', message: error instanceof Error ? error.message : '未知错误' })
    }
    setIsEditing(false)
  }

  const handleCancelEdit = () => {
    setEditName(canvas.name)
    setIsEditing(false)
  }

  const handleDelete = async () => {
    if (!confirm(`确定要删除画布"${canvas.name}"吗？此操作不可恢复。`)) {
      return
    }

    try {
      await deleteCanvas(canvas.id)
      addToast({ type: 'success', title: '已删除', message: '画布已被删除' })
      setShowContextMenu(false)
    } catch (error) {
      addToast({ type: 'error', title: '删除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setContextMenuPosition({ x: e.clientX, y: e.clientY })
    setShowContextMenu(true)
    setShowMoveMenu(false)
  }

  const handleMoveToFolder = async (targetFolderId: number | null) => {
    try {
      await updateCanvas(canvas.id, { folderId: targetFolderId })
      const folderName = targetFolderId ? folders.find(f => f.id === targetFolderId)?.name : '根目录'
      addToast({ type: 'success', title: '已移动', message: `画布已移动到"${folderName}"` })
      setShowContextMenu(false)
      setShowMoveMenu(false)
    } catch (error) {
      addToast({ type: 'error', title: '移动失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSaveEdit()
    } else if (e.key === 'Escape') {
      handleCancelEdit()
    }
  }

  return (
    <div className="relative group mb-2">
      {isEditing ? (
        // 编辑模式
        <div className="p-2 rounded bg-blue-50 dark:bg-blue-900/30">
          <input
            ref={inputRef}
            type="text"
            value={editName}
            onChange={(e) => setEditName(e.target.value)}
            onKeyDown={handleKeyDown}
            className="w-full text-sm bg-white dark:bg-gray-800 border border-blue-500 rounded px-2 py-1.5 outline-none text-gray-700 dark:text-gray-300 mb-2"
            placeholder="画布名称"
          />
          <div className="flex items-center gap-2">
            <button
              onClick={handleSaveEdit}
              className="flex-1 flex items-center justify-center gap-1 px-2 py-1 text-sm bg-green-600 hover:bg-green-700 text-white rounded transition-colors"
            >
              <Check className="w-3 h-3" />
              保存
            </button>
            <button
              onClick={handleCancelEdit}
              className="flex-1 flex items-center justify-center gap-1 px-2 py-1 text-sm bg-gray-400 hover:bg-gray-500 text-white rounded transition-colors"
            >
              <X className="w-3 h-3" />
              取消
            </button>
          </div>
        </div>
      ) : (
        // 查看模式 - 缩略图卡片
        <>
          {/* 插入指示线 - 上方 */}
          {dragOverItem?.type === 'canvas' && dragOverItem?.id === canvas.id && dragOverItem?.position === 'before' && (
            <div className="h-0.5 bg-blue-500 rounded -mt-1 mb-1" />
          )}
          {/* 插入指示线 - 下方 */}
          {dragOverItem?.type === 'canvas' && dragOverItem?.id === canvas.id && dragOverItem?.position === 'after' && (
            <div className="h-0.5 bg-blue-500 rounded -mb-1 mt-1" />
          )}

          <div
            draggable
            onDragStart={(e) => onDragStart(e, canvas, 'canvas')}
            onDragOver={(e) => onDragOver(e, canvas, 'canvas')}
            onDragLeave={onDragLeave}
            onDrop={(e) => onDrop(e, canvas, 'canvas')}
            onContextMenu={handleContextMenu}
            className={clsx(
              'relative rounded-lg border bg-white dark:bg-gray-800 hover:shadow-lg transition-all cursor-pointer group overflow-hidden',
              isActive
                ? 'border-blue-500 ring-2 ring-blue-500/20 shadow-blue-500/10'
                : 'border-gray-200 dark:border-gray-700 hover:border-blue-400 dark:hover:border-blue-500'
            )}
          >
            {isActive && (
              <div className="absolute top-2 right-2 z-10">
                <div className="bg-blue-500 text-white text-[10px] font-extrabold px-1.5 py-0.5 rounded shadow-sm flex items-center gap-1">
                  <div className="w-1 h-1 rounded-full bg-white animate-pulse" />
                  OPENING
                </div>
              </div>
            )}
            {/* 缩略图区域 */}
            <div
              onClick={() => navigate(`/canvas/${canvas.id}`)}
              className="aspect-video bg-gradient-to-br from-gray-100 to-gray-200 dark:from-gray-700 dark:to-gray-800 rounded-t-lg relative overflow-hidden"
            >
            {canvas.thumbnail ? (
              <img
                src={canvas.thumbnail}
                alt={canvas.name}
                className="w-full h-full object-cover"
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center">
                <FileText className="w-8 h-8 text-gray-400 dark:text-gray-600" />
              </div>
            )}

            {/* 悬停时的遮罩 */}
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
              <span className="text-white opacity-0 group-hover:opacity-100 transition-opacity text-sm font-medium">
                打开画布
              </span>
            </div>
          </div>

          {/* 画布信息 */}
          <div className="p-2">
            <h4
              onClick={() => navigate(`/canvas/${canvas.id}`)}
              className="text-sm font-medium text-gray-900 dark:text-white truncate pr-6"
            >
              {canvas.name}
            </h4>
            {canvas.updatedAt && (
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                {new Date(canvas.updatedAt).toLocaleDateString()}
              </p>
            )}
          </div>

          {/* 右键菜单 */}
          {showContextMenu && (
            <div
              ref={contextMenuRef}
              className="fixed bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50 min-w-[160px]"
              style={{
                left: contextMenuPosition.x,
                top: contextMenuPosition.y
              }}
            >
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  setShowMoveMenu(!showMoveMenu)
                }}
                className="w-full flex items-center justify-between gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                <div className="flex items-center gap-2">
                  <Folder className="w-3 h-3" />
                  移动到
                </div>
                <span className="text-gray-400">›</span>
              </button>

              {showMoveMenu && (
                <div className="border-t border-gray-200 dark:border-gray-700">
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      handleMoveToFolder(null)
                    }}
                    className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                  >
                    <span className="w-3 h-3" />
                    根目录
                  </button>
                  {folders.map((folder) => (
                    <button
                      key={folder.id}
                      onClick={(e) => {
                        e.stopPropagation()
                        handleMoveToFolder(folder.id)
                      }}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                    >
                      <Folder className="w-3 h-3" />
                      {folder.name}
                    </button>
                  ))}
                </div>
              )}

              <button
                onClick={(e) => {
                  e.stopPropagation()
                  handleStartEdit()
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                <Edit2 className="w-3 h-3" />
                重命名
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  handleDelete()
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30"
              >
                <Trash2 className="w-3 h-3" />
                删除
              </button>
            </div>
          )}
        </div>
        </>
      )}
    </div>
  )
}
