/**
 * DragOverlay Component
 *
 * Renders a visual preview of the item being dragged.
 * Uses @dnd-kit's DragOverlay for smooth, performant drag previews.
 */

import { memo } from 'react'
import { DragOverlay as DndDragOverlay } from '@dnd-kit/core'
import type { NodeCard, NodePoolFolder } from '@/types'
import type { DragOverlayProps } from '../types/node-pool'
import { createDraggableId, parseDraggableId } from '../types/node-pool'
import { useNodePoolStore } from '../stores/useNodePoolStore'

/**
 * Props for the draggable preview content
 */
interface DraggablePreviewProps {
  /** The data of the item being dragged */
  data: {
    type: 'folder' | 'card'
    id: number
    name: string
    color?: string
    card?: NodeCard
    folder?: NodePoolFolder
  }
}

/**
 * Preview for a folder being dragged
 */
const FolderPreview = memo(({ folder }: { folder: NodePoolFolder }) => {
  return (
    <div className="flex items-center gap-2 px-3 py-2 bg-white dark:bg-gray-800 rounded-lg shadow-xl border-2 border-blue-500 opacity-90 min-w-[200px]">
      <div className="w-4 h-4 text-blue-500">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" />
        </svg>
      </div>
      <span className="text-sm font-medium text-gray-800 dark:text-white">
        {folder.name}
      </span>
    </div>
  )
})
FolderPreview.displayName = 'FolderPreview'

/**
 * Preview for a card being dragged
 */
const CardPreview = memo(({ card }: { card: NodeCard }) => {
  // Try to parse card content for preview
  let previewContent: React.ReactNode = null

  try {
    const nodeData = JSON.parse(card.content)
    const title = nodeData.title || card.name
    const content = nodeData.content || ''

    previewContent = (
      <div className="w-[280px] rounded-lg shadow-xl border-2 border-blue-500 overflow-hidden opacity-90">
        <div
          className="px-4 py-3"
          style={{ backgroundColor: card.color || '#ffffff' }}
        >
          <div className="flex items-start justify-between gap-2">
            <h4 className="text-sm font-medium text-gray-800 dark:text-white truncate flex-1">
              {title}
            </h4>
          </div>
          {content && (
            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
              {content}
            </p>
          )}
        </div>
      </div>
    )
  } catch {
    // Fallback if content parsing fails
    previewContent = (
      <div className="w-[280px] rounded-lg shadow-xl border-2 border-blue-500 overflow-hidden opacity-90">
        <div
          className="px-4 py-3"
          style={{ backgroundColor: card.color || '#ffffff' }}
        >
          <h4 className="text-sm font-medium text-gray-800 dark:text-white">
            {card.name}
          </h4>
        </div>
      </div>
    )
  }

  return previewContent
})
CardPreview.displayName = 'CardPreview'

/**
 * Main drag overlay component
 */
export const DragOverlay = memo(({ activeDragData }: DragOverlayProps) => {
  if (!activeDragData) {
    return null
  }

  const { type, numericId } = activeDragData

  // The actual data will be retrieved from the store
  // For now, we render a placeholder that will be updated
  return (
    <DndDragOverlay>
      {type === 'folder' ? (
        <FolderPlaceholder id={numericId} />
      ) : (
        <CardPlaceholder id={numericId} />
      )}
    </DndDragOverlay>
  )
})
DragOverlay.displayName = 'DragOverlay'

/**
 * Placeholder component that fetches the actual folder data
 */
const FolderPlaceholder = memo(({ id }: { id: number }) => {
  const folder = useNodePoolStore((state) => state.foldersMap.get(id))

  if (!folder) {
    return null
  }

  return <FolderPreview folder={folder} />
})

/**
 * Placeholder component that fetches the actual card data
 */
const CardPlaceholder = memo(({ id }: { id: number }) => {
  const card = useNodePoolStore((state) => state.cardsMap.get(id))

  if (!card) {
    return null
  }

  return <CardPreview card={card} />
})

export type { DragOverlayProps, DraggablePreviewProps }
