/**
 * useNodePoolDrag Hook
 *
 * Core drag and drop logic using @dnd-kit.
 * Handles drag events and coordinates with the sort system.
 */

import { useCallback, useEffect, useRef } from 'react'
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  KeyboardSensor,
  useSensor,
  useSensors,
  DragOverlay,
  closestCenter,
  PointerActivationConstraint,
  Modifiers,
} from '@dnd-kit/core'
import type { Sensor } from '@dnd-kit/core'
import type { NodeCard, NodePoolFolder } from '@/types'
import { useNodePoolStore } from '../stores/useNodePoolStore'
import type {
  DragData,
  DragOverData,
  DropPosition,
  DraggableId,
  DraggableType,
  ReorderOperation,
  UseNodePoolDragOptions,
  UseNodePoolDragReturn,
} from '../types/node-pool'
import { createDraggableId, parseDraggableId } from '../types/node-pool'

/**
 * Default activation constraint for pointer sensor
 */
const DEFAULT_ACTIVATION_CONSTRAINT: PointerActivationConstraint = {
  distance: 8, // 8px movement required to start dragging
}

/**
 * Check if an item can be dropped at a target location
 */
function canDropAt(
  activeType: DraggableType,
  overType: DraggableType,
  position: DropPosition
): boolean {
  // Same type can always be reordered
  if (activeType === overType) {
    return true
  }

  // Cards can be dropped inside folders
  if (activeType === 'card' && overType === 'folder' && position === 'inside') {
    return true
  }

  // Cards cannot be placed before/after folders
  if (activeType === 'card' && overType === 'folder') {
    return false
  }

  // Folders cannot be dropped inside cards
  if (activeType === 'folder' && overType === 'card') {
    return false
  }

  return false
}

/**
 * Calculate drop position based on mouse event and target rect
 */
function calculateDropPosition(
  event: DragOverEvent,
  overId: DraggableId
): DropPosition {
  const overData = parseDraggableId(overId)

  // For folders, default to 'inside'
  if (overData.type === 'folder') {
    return 'inside'
  }

  // For cards, calculate based on mouse position
  const activatorEvent = event.activatorEvent
  if (!activatorEvent || activatorEvent.type !== 'mousemove') {
    return 'after'
  }

  // Get the target element's bounding rectangle
  const targetElement = document.querySelector(`[data-dnd-id="${overId}"]`)
  if (!targetElement) {
    return 'after'
  }

  const rect = targetElement.getBoundingClientRect()
  const mouseY = (activatorEvent as MouseEvent).clientY
  const midpoint = rect.top + rect.height / 2

  return mouseY < midpoint ? 'before' : 'after'
}

/**
 * Custom hook for node pool drag and drop functionality
 */
export function useNodePoolDrag(options: UseNodePoolDragOptions): UseNodePoolDragReturn {
  const { onDragStart, onDragEnd, onReorder, onDropOnCanvas } = options
  const {
    dragState,
    setDragState,
    clearDragState,
    cardsMap,
    foldersMap,
    getCard,
    getFolder,
  } = useNodePoolStore()
  const get = useNodePoolStore.getState
  const dragStartPos = useRef<{ x: number; y: number } | null>(null)

  // Pointer sensor configuration (mouse/touch)
  const pointerSensor = useSensor(PointerSensor, {
    activationConstraint: DEFAULT_ACTIVATION_CONSTRAINT,
  })

  // Keyboard sensor configuration (accessibility)
  const keyboardSensor = useSensor(KeyboardSensor, {
    coordinateGetter: (event, { context }) => {
      const { active, over } = context
      if (active && over) {
        return {
          x: 0,
          y: 0,
        }
      }
      return null
    },
  })

  const sensors = useSensors(pointerSensor, keyboardSensor)

  // Handle drag start
  const handleDragStart = useCallback((event: DragStartEvent) => {
    const { active } = event
    const id = active.id as DraggableId
    const { type, numericId } = parseDraggableId(id)

    let dragData: DragData | null = null

    if (type === 'folder') {
      const folder = getFolder(numericId)
      if (folder) {
        dragData = {
          id,
          type,
          numericId,
          folderId: null,
          parentId: folder.parentId || null,
        }
      }
    } else {
      const card = getCard(numericId)
      if (card) {
        dragData = {
          id,
          type,
          numericId,
          folderId: card.folderId || null,
          parentId: null,
        }

        // Store initial position for drag-to-canvas detection
        const activatorEvent = event.activatorEvent
        if (activatorEvent && activatorEvent.type === 'mousedown') {
          dragStartPos.current = {
            x: (activatorEvent as MouseEvent).clientX,
            y: (activatorEvent as MouseEvent).clientY,
          }
        }
      }
    }

    if (dragData) {
      setDragState({ active: dragData, over: null })
      onDragStart?.(dragData)
    }
  }, [getCard, getFolder, setDragState, onDragStart])

  // Handle drag over (determine drop position)
  const handleDragOver = useCallback((event: DragOverEvent) => {
    const { active, over } = event

    if (!over) {
      setDragState({ active: get().dragState.active, over: null })
      return
    }

    const activeId = active.id as DraggableId
    const overId = over.id as DraggableId

    // Can't drop on self
    if (activeId === overId) {
      return
    }

    const activeData = parseDraggableId(activeId)
    const overData = parseDraggableId(overId)

    // Calculate drop position
    let position: DropPosition = calculateDropPosition(event, overId)

    // Check if drop is allowed
    if (!canDropAt(activeData.type, overData.type, position)) {
      setDragState({ active: get().dragState.active, over: null })
      return
    }

    setDragState({
      active: get().dragState.active,
      over: {
        id: overId,
        type: overData.type,
        numericId: overData.numericId,
        position,
      },
    })
  }, [get, setDragState])

  // Handle drag end
  const handleDragEnd = useCallback(async (event: DragEndEvent) => {
    const { active, over } = event
    const activeId = active.id as DraggableId
    const dragData = get().dragState.active

    try {
      if (!dragData) {
        return
      }

      // Check if this is a drop on canvas (outside the node pool)
      if (!over) {
        // Check if we moved significantly from start position
        const activatorEvent = event.activatorEvent
        if (
          activatorEvent &&
          activatorEvent.type === 'mouseup' &&
          dragStartPos.current &&
          onDropOnCanvas
        ) {
          const endX = (activatorEvent as MouseEvent).clientX
          const endY = (activatorEvent as MouseEvent).clientY
          const distance = Math.sqrt(
            Math.pow(endX - dragStartPos.current.x, 2) +
            Math.pow(endY - dragStartPos.current.y, 2)
          )

          // If moved more than 50px, consider it a canvas drop
          if (distance > 50) {
            await onDropOnCanvas(dragData, { x: endX, y: endY })
          }
        }
        return
      }

      const overId = over.id as DraggableId
      const activeData = parseDraggableId(activeId)
      const overData = parseDraggableId(overId)

      // Get current drop position from state
      const position = get().dragState.over?.position || 'after'

      // Check if drop is allowed
      if (!canDropAt(activeData.type, overData.type, position)) {
        return
      }

      // Handle dropping card inside folder
      if (activeData.type === 'card' && overData.type === 'folder' && position === 'inside') {
        // This will be handled by the card's folder update logic
        // For now, we'll handle it through a special operation
        const operation: ReorderOperation = {
          type: 'reorder-card',
          itemId: activeData.numericId,
          targetId: overData.numericId,
          position: 'after',
          folderId: overData.numericId, // Move to this folder
          parentId: overData.numericId,
        }
        await onReorder(operation)
        return
      }

      // Handle same-type reordering
      if (activeData.type === overData.type) {
        const operation: ReorderOperation = {
          type: activeData.type === 'folder' ? 'reorder-folder' : 'reorder-card',
          itemId: activeData.numericId,
          targetId: overData.numericId,
          position: position === 'inside' ? 'after' : position,
          folderId: activeData.type === 'card'
            ? (getCard(activeData.numericId)?.folderId || null)
            : null,
          parentId: activeData.type === 'folder'
            ? (getFolder(activeData.numericId)?.parentId || null)
            : null,
        }

        await onReorder(operation)
      }
    } finally {
      // Clean up
      dragStartPos.current = null
      clearDragState()
      onDragEnd?.(null)
    }
  }, [get, getCard, getFolder, clearDragState, onDragEnd, onReorder, onDropOnCanvas])

  // Clean up drag state on unmount
  useEffect(() => {
    return () => {
      clearDragState()
      dragStartPos.current = null
    }
  }, [clearDragState])

  return {
    sensors: sensors as unknown as any[],
    activeDragData: dragState.active,
    setDragOver: (over: DragOverData | null) => {
      setDragState({ active: get().dragState.active, over })
    },
  }
}

/**
 * Extended options including canvas drop support
 */
export interface ExtendedDndOptions {
  onReorder: (operation: ReorderOperation) => Promise<void>
  onDragStart?: (data: DragData) => void
  onDragEnd?: (data: DragData | null) => void
  onDropOnCanvas?: (data: DragData, position: { x: number; y: number }) => Promise<void>
}

/**
 * Props for the DndContextProvider component
 */
export interface DndContextProviderProps {
  children: React.ReactNode
  onReorder: (operation: ReorderOperation) => Promise<void>
  onDragStart?: (data: DragData) => void
  onDragEnd?: (data: DragData | null) => void
  onDropOnCanvas?: (data: DragData, position: { x: number; y: number }) => Promise<void>
}

/**
 * Provider component that sets up the DnD context
 */
export function DndContextProvider({
  children,
  onReorder,
  onDragStart,
  onDragEnd,
  onDropOnCanvas,
}: DndContextProviderProps) {
  const { sensors, activeDragData } = useNodePoolDrag({
    onReorder,
    onDragStart,
    onDragEnd,
    onDropOnCanvas,
  })

  const handleDragStart = useCallback((event: DragStartEvent) => {
    // Event is handled by the hook
  }, [])

  const handleDragOver = useCallback((event: DragOverEvent) => {
    // Event is handled by the hook
  }, [])

  const handleDragEnd = useCallback((event: DragEndEvent) => {
    // Event is handled by the hook
  }, [])

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDragEnd={handleDragEnd}
    >
      {children}
    </DndContext>
  )
}

