/**
 * NodePoolPanel Component - With FLIP Animations
 *
 * Main container for the node pool feature.
 * Includes SortableContext for smooth FLIP animations during drag.
 */

import { useState, useCallback, useEffect, useMemo } from 'react'
import {
  Plus,
  Search,
  FolderPlus,
  SortAsc,
  SortDesc,
  X,
} from 'lucide-react'
import { clsx } from 'clsx'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useUIStore } from '@/store/useUIStore'
import { useCanvasStore } from '@/store/useCanvasStore'
import type { NodeCard, NodePoolFolder } from '@/types'
import type { NodePoolSortOption, NodePoolSortOrder } from '@/types'
import type { DragData } from '../types/node-pool'
import { createDraggableId } from '../types/node-pool'
import { useNodePoolStore } from '../stores/useNodePoolStore'
import { useNodePoolSort, useFolderTree } from '../hooks/useNodePoolSort'
import { DndContextProvider } from '../hooks/useNodePoolDrag'
import { DragOverlay } from './DragOverlay'
import { FolderItem } from './FolderItem'
import { NodeCardItem } from './NodeCardItem'

interface NodePoolPanelProps {
  open: boolean
}

/**
 * Get draggable IDs for SortableContext
 */
function getDraggableIds(items: Array<{ id: number }>): string[] {
  return items.map((item) => createDraggableId('card', item.id))
}

function getFolderDraggableIds(items: Array<{ id: number }>): string[] {
  return items.map((item) => createDraggableId('folder', item.id))
}

/**
 * Main node pool panel component
 */
export function NodePoolPanel({ open }: NodePoolPanelProps) {
  const { currentProject } = useProjectsStore()
  const { selectedIds, addNode } = useCanvasStore()
  const { addToast } = useUIStore()

  // Node pool store
  const {
    cardsMap,
    foldersMap,
    setCards,
    setFolders,
    updateCard,
    removeCard,
    createFolder,
    toggleFolderCollapsed,
    dragState,
  } = useNodePoolStore()

  // Sort functionality
  const { sortedRootFolders, sortedCardsByFolder, handleReorder } = useNodePoolSort()
  const folderTree = useFolderTree()

  // Local state
  const [searchQuery, setSearchQuery] = useState('')
  const [sortBy, setSortBy] = useState<NodePoolSortOption>('createdAt')
  const [sortOrder, setSortOrder] = useState<NodePoolSortOrder>('desc')
  const [showNewFolderInput, setShowNewFolderInput] = useState(false)
  const [newFolderName, setNewFolderName] = useState('')

  // Load data when project changes
  useEffect(() => {
    if (currentProject) {
      const existingCards = useProjectsStore.getState().nodePool
      const existingFolders = useProjectsStore.getState().nodePoolFolders

      setCards(existingCards)
      setFolders(existingFolders)
    }
  }, [currentProject, setCards, setFolders])

  // Prepare draggable IDs for SortableContext
  const rootFolderIds = useMemo(() => {
    return getFolderDraggableIds(sortedRootFolders)
  }, [sortedRootFolders])

  const rootCardIds = useMemo(() => {
    const rootCards = sortedCardsByFolder.get(null) || []
    return getDraggableIds(rootCards)
  }, [sortedCardsByFolder])

  // Handle add selected node to pool
  const handleAddToPool = useCallback(async () => {
    if (selectedIds.length === 0) {
      addToast({ type: 'warning', title: '未选择节点', message: '请选择一个节点添加到节点池' })
      return
    }

    const nodeId = selectedIds[0]
    const nodes = useCanvasStore.getState().nodes
    const node = nodes.get(nodeId)
    if (!node) return

    try {
      await useProjectsStore.getState().addToNodePool(currentProject!.id, {
        projectId: currentProject!.id,
        name: node.title || node.content || '未命名',
        content: JSON.stringify(node),
        type: node.type || 'text',
        color: node.color,
        tags: null,
        createdBy: 1,
        sortOrder: 0,
      })

      const updatedCards = useProjectsStore.getState().nodePool
      setCards(updatedCards)

      addToast({ type: 'success', title: '已添加到节点池', message: '节点已添加到节点池' })
    } catch (error) {
      addToast({ type: 'error', title: '添加失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }, [selectedIds, currentProject, addToast, setCards])

  // Handle drop on canvas (from node pool)
  const handleDropOnCanvas = useCallback(async (data: DragData, position: { x: number; y: number }) => {
    if (data.type !== 'card') {
      return
    }

    const card = cardsMap.get(data.numericId)
    if (!card) {
      return
    }

    try {
      const nodeData = JSON.parse(card.content)

      const canvasElement = document.querySelector('[data-canvas-container]')
      if (!canvasElement) {
        addToast({ type: 'error', title: '拖放失败', message: '无法找到画布容器' })
        return
      }

      const canvasRect = canvasElement.getBoundingClientRect()
      const relativeX = position.x - canvasRect.left
      const relativeY = position.y - canvasRect.top

      const newNode = {
        ...nodeData,
        id: `${nodeData.id}-pool-${Date.now()}`,
        x: relativeX,
        y: relativeY,
      }
      addNode(newNode)

      await removeCard(card.id)

      const updatedCards = useProjectsStore.getState().nodePool
      setCards(updatedCards)

      addToast({ type: 'success', title: '节点已取出', message: '卡片已拖到画布' })
    } catch (error) {
      addToast({ type: 'error', title: '使用节点失败', message: '无法解析节点数据' })
    }
  }, [cardsMap, addNode, removeCard, setCards, addToast])

  // Handle use card from pool (for click-to-use)
  const handleUseCard = useCallback(async (card: NodeCard) => {
    try {
      const nodeData = JSON.parse(card.content)
      const newNode = {
        ...nodeData,
        id: `${nodeData.id}-pool-${Date.now()}`,
        x: nodeData.x + 50,
        y: nodeData.y + 50,
      }
      addNode(newNode)

      await removeCard(card.id)

      const updatedCards = useProjectsStore.getState().nodePool
      setCards(updatedCards)

      addToast({ type: 'success', title: '节点已取出', message: '卡片已从池中取出到画布' })
    } catch (error) {
      addToast({ type: 'error', title: '使用节点失败', message: '无法解析节点数据' })
    }
  }, [addNode, removeCard, setCards, addToast])

  // Handle remove card
  const handleRemoveCard = useCallback(async (id: number) => {
    try {
      await removeCard(id)
      addToast({ type: 'success', title: '已移除', message: '节点卡片已移除' })
    } catch (error) {
      addToast({ type: 'error', title: '移除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }, [removeCard, addToast])

  // Handle save card name
  const handleSaveCardName = useCallback(async (id: number, name: string) => {
    try {
      await updateCard(id, { name })
      addToast({ type: 'success', title: '已更新', message: '卡片名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '更新失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }, [updateCard, addToast])

  // Handle sort change
  const handleSortChange = useCallback((newSortBy: NodePoolSortOption) => {
    if (sortBy === newSortBy) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')
    } else {
      setSortBy(newSortBy)
      setSortOrder('desc')
    }
  }, [sortBy, sortOrder])

  // Handle folder collapse toggle
  const handleToggleFolder = useCallback((id: number) => {
    toggleFolderCollapsed(id)
  }, [toggleFolderCollapsed])

  // Handle folder creation
  const handleCreateFolder = useCallback(async () => {
    if (!newFolderName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入文件夹名称' })
      return
    }

    if (!currentProject) {
      addToast({ type: 'error', title: '创建失败', message: '请先选择一个项目' })
      return
    }

    try {
      // Get the max sort order to add at the end
      const folders = Array.from(foldersMap.values())
      const maxSortOrder = folders.length > 0 ? Math.max(...folders.map(f => f.sortOrder)) : -1

      await createFolder({
        projectId: currentProject.id,
        name: newFolderName.trim(),
        parentId: null,
        collapsed: false,
        sortOrder: maxSortOrder + 10,
      })

      // Reload folders from store
      const updatedFolders = useProjectsStore.getState().nodePoolFolders
      setFolders(updatedFolders)

      addToast({ type: 'success', title: '文件夹已创建', message: '文件夹创建成功' })
      setNewFolderName('')
      setShowNewFolderInput(false)
    } catch (error) {
      addToast({ type: 'error', title: '创建失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }, [newFolderName, currentProject, foldersMap, createFolder, setFolders, addToast])

  // Filter cards based on search
  const filteredCards = useCallback(() => {
    if (!searchQuery.trim()) {
      return Array.from(cardsMap.values())
    }

    const searchTerms = searchQuery.trim().toLowerCase().split(/\s+/).filter(term => term.length > 0)
    return Array.from(cardsMap.values()).filter((card) => {
      const name = card.name.toLowerCase()
      let content = ''

      try {
        const nodeData = JSON.parse(card.content)
        content = (nodeData.content || '').toLowerCase()
      } catch {
        content = card.content.toLowerCase()
      }

      return searchTerms.every(term => name.includes(term) || content.includes(term))
    })
  }, [cardsMap, searchQuery])

  // Render folder with its contents
  const renderFolder = (folder: NodePoolFolder & { children?: NodePoolFolder[] }, level = 0) => {
    const cards = sortedCardsByFolder.get(folder.id) || []
    const folderIds = useMemo(() => {
      const childFolders = folder.children || []
      return getFolderDraggableIds(childFolders)
    }, [folder.children])

    const cardIds = useMemo(() => {
      return getDraggableIds(cards)
    }, [cards])

    return (
      <SortableFolderItem
        key={folder.id}
        folder={folder}
        level={level}
        cards={cards}
        children={folder.children || []}
        childFolderIds={folderIds}
        cardIds={cardIds}
        isDragOver={false}
        dragOverPosition={null}
        onToggle={handleToggleFolder}
        onUse={handleUseCard}
        onRemove={handleRemoveCard}
        onSaveName={handleSaveCardName}
      />
    )
  }

  if (!open) {
    return null
  }

  return (
    <DndContextProvider
      onReorder={handleReorder}
      onDropOnCanvas={handleDropOnCanvas}
    >
      <aside className="w-72 bg-white dark:bg-gray-800 border-l border-gray-200 dark:border-gray-700 flex flex-col">
        {/* Header */}
        <div className="h-12 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between px-4 flex-shrink-0">
          <h2 className="font-semibold text-gray-800 dark:text-white">节点池</h2>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setShowNewFolderInput(!showNewFolderInput)}
              className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
              title="新建文件夹"
            >
              <FolderPlus className="w-4 h-4" />
            </button>
            <button
              onClick={handleAddToPool}
              className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
              title="添加选中节点到池"
            >
              <Plus className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* New folder input */}
        {showNewFolderInput && (
          <div className="p-3 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
            <div className="flex gap-2">
              <input
                type="text"
                placeholder="文件夹名称..."
                value={newFolderName}
                onChange={(e) => setNewFolderName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault()
                    handleCreateFolder()
                  } else if (e.key === 'Escape') {
                    e.preventDefault()
                    setNewFolderName('')
                    setShowNewFolderInput(false)
                  }
                }}
                className="flex-1 px-2 py-1 text-sm bg-gray-100 dark:bg-gray-700 border-0 rounded focus:ring-2 focus:ring-blue-500 text-gray-800 dark:text-white"
              />
              <button
                onClick={handleCreateFolder}
                className="px-3 py-1 text-sm bg-blue-500 text-white rounded hover:bg-blue-600"
              >
                创建
              </button>
              <button
                onClick={() => setShowNewFolderInput(false)}
                className="p-1 text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        {/* Search and Sort */}
        <div className="p-3 border-b border-gray-200 dark:border-gray-700 flex-shrink-0">
          <div className="relative mb-2">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="搜索节点..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-3 py-2 text-sm bg-gray-100 dark:bg-gray-700 border-0 rounded-lg focus:ring-2 focus:ring-blue-500 text-gray-800 dark:text-white placeholder-gray-500"
            />
          </div>

          {/* Sort buttons */}
          <div className="flex gap-1">
            <button
              onClick={() => handleSortChange('name')}
              className={clsx(
                'flex-1 px-2 py-1 text-xs rounded flex items-center justify-center gap-1',
                sortBy === 'name'
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                  : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
              )}
            >
              名称
              {sortBy === 'name' && (
                sortOrder === 'asc' ? <SortAsc className="w-3 h-3" /> : <SortDesc className="w-3 h-3" />
              )}
            </button>
            <button
              onClick={() => handleSortChange('createdAt')}
              className={clsx(
                'flex-1 px-2 py-1 text-xs rounded flex items-center justify-center gap-1',
                sortBy === 'createdAt'
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                  : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
              )}
            >
              创建时间
              {sortBy === 'createdAt' && (
                sortOrder === 'asc' ? <SortAsc className="w-3 h-3" /> : <SortDesc className="w-3 h-3" />
              )}
            </button>
          </div>
        </div>

        {/* Content with SortableContext for root items */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-3">
          {/* Root folders with SortableContext */}
          {rootFolderIds.length > 0 && (
            <SortableContext
              items={rootFolderIds}
              strategy={verticalListSortingStrategy}
            >
              {folderTree.map((folder) => renderFolder(folder))}
            </SortableContext>
          )}

          {/* Root cards with SortableContext */}
          {rootCardIds.length > 0 && (
            <SortableContext
              items={rootCardIds}
              strategy={verticalListSortingStrategy}
            >
              {sortedCardsByFolder.get(null)?.map((card) => (
                <div key={card.id} className="mb-2">
                  <NodeCardItem
                    card={card}
                    isDragging={false}
                    isDragOver={false}
                    dragOverPosition={null}
                    onUse={handleUseCard}
                    onRemove={handleRemoveCard}
                    onSaveName={handleSaveCardName}
                    onContextMenu={(e, c) => {
                      e.preventDefault()
                    }}
                  />
                </div>
              ))}
            </SortableContext>
          )}

          {/* Empty state */}
          {cardsMap.size === 0 && (
            <div className="text-center py-8 text-gray-500 dark:text-gray-400">
              <p className="text-sm">节点池为空</p>
              <p className="text-xs mt-1">选择节点并点击 + 添加</p>
            </div>
          )}
        </div>

        {/* Drag Overlay */}
        <DragOverlay activeDragData={dragState.active} />
      </aside>
    </DndContextProvider>
  )
}

/**
 * Sortable Folder Item Component
 * Wraps FolderItem with SortableContext for children
 */
interface SortableFolderItemProps {
  folder: NodePoolFolder & { children?: NodePoolFolder[] }
  level?: number
  cards: NodeCard[]
  children: NodePoolFolder[]
  childFolderIds: string[]
  cardIds: string[]
  isDragOver: boolean
  dragOverPosition: 'before' | 'after' | null
  onToggle: (id: number) => void
  onUse: (card: NodeCard) => void
  onRemove: (id: number) => void
  onSaveName: (id: number, name: string) => void
}

function SortableFolderItem({
  folder,
  level = 0,
  cards,
  children,
  childFolderIds,
  cardIds,
  isDragOver,
  dragOverPosition,
  onToggle,
  onUse,
  onRemove,
  onSaveName,
}: SortableFolderItemProps) {
  const isCollapsed = folder.collapsed

  return (
    <div className="mb-2">
      <FolderItem
        folder={folder}
        level={level}
        cards={cards}
        children={children}
        isDragOver={isDragOver}
        dragOverPosition={dragOverPosition}
        onToggle={onToggle}
      />

      {/* Expanded content with nested SortableContext */}
      {!isCollapsed && (
        <div className="ml-4 pl-2 border-l border-gray-200 dark:border-gray-700 my-1 space-y-1">
          {/* Cards in this folder */}
          {cardIds.length > 0 && (
            <SortableContext
              items={cardIds}
              strategy={verticalListSortingStrategy}
            >
              {cards.map((card) => (
                <div key={card.id} className="py-0.5">
                  <NodeCardItem
                    card={card}
                    isDragging={false}
                    isDragOver={false}
                    dragOverPosition={null}
                    onUse={onUse}
                    onRemove={onRemove}
                    onSaveName={onSaveName}
                    onContextMenu={(e, c) => {
                      e.preventDefault()
                    }}
                  />
                </div>
              ))}
            </SortableContext>
          )}

          {/* Nested folders */}
          {childFolderIds.length > 0 && (
            <SortableContext
              items={childFolderIds}
              strategy={verticalListSortingStrategy}
            >
              {children.map((child) => (
                <SortableFolderItem
                  key={child.id}
                  folder={child}
                  level={level + 1}
                  cards={[]} // Cards fetched by parent
                  children={child.children || []}
                  childFolderIds={[]} // Computed recursively
                  cardIds={[]} // Computed recursively
                  isDragOver={false}
                  dragOverPosition={null}
                  onToggle={onToggle}
                  onUse={onUse}
                  onRemove={onRemove}
                  onSaveName={onSaveName}
                />
              ))}
            </SortableContext>
          )}
        </div>
      )}
    </div>
  )
}

export default NodePoolPanel
